import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"版权与 DMCA","description":"版权提示、合规要求与侵权投诉流程。","frontmatter":{"title":"版权与 DMCA","description":"版权提示、合规要求与侵权投诉流程。","order":52,"group":"legal"},"headers":[],"relativePath":"copyright.md","filePath":"copyright.md"}'),o={name:"copyright.md"};function r(c,a,d,n,h,s){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="版权与-dmca" tabindex="-1">版权与 DMCA <a class="header-anchor" href="#版权与-dmca" aria-label="Permalink to &quot;版权与 DMCA&quot;">​</a></h1><h2 id="_1-基本原则" tabindex="-1">1. 基本原则 <a class="header-anchor" href="#_1-基本原则" aria-label="Permalink to &quot;1. 基本原则&quot;">​</a></h2><ul><li>MetaFusion 是资源收录与编目平台，<strong>不鼓励亦不支持侵权分发</strong>。</li><li>媒体预览与下载页需展示版权与合规提示，下载行为需二次确认。</li><li>元数据（事实性信息、结构化描述）与媒体二进制（受版权保护的文件）适用不同规则：前者开放，后者受控且需合规使用。</li></ul><h2 id="_2-提交保证" tabindex="-1">2. 提交保证 <a class="header-anchor" href="#_2-提交保证" aria-label="Permalink to &quot;2. 提交保证&quot;">​</a></h2><ul><li>你保证拥有提交内容的必要权利，或属于合理使用、公共领域、已获授权。</li><li>鼓励提供 <code>source_urls</code> 与 <code>edit_note</code> 以证明来源与考据过程。</li></ul><h2 id="_3-侵权投诉-dmca-风格" tabindex="-1">3. 侵权投诉（DMCA 风格） <a class="header-anchor" href="#_3-侵权投诉-dmca-风格" aria-label="Permalink to &quot;3. 侵权投诉（DMCA 风格）&quot;">​</a></h2><p>若你认为站内内容侵犯你的版权，请通过<a href="/docs/contact">联系方式</a>提交：</p><ul><li>权利人身份与联系方式</li><li>被侵权作品的描述与权属证明</li><li>侵权内容在站内的具体 URL（Work/Release/Asset ID 与链接）</li><li>声明“善意相信该使用未经授权”与“信息准确、愿承担伪证责任”</li></ul><p>站务将在核实后下架或限制访问，并通知上传者。</p><h2 id="_4-反通知" tabindex="-1">4. 反通知 <a class="header-anchor" href="#_4-反通知" aria-label="Permalink to &quot;4. 反通知&quot;">​</a></h2><p>上传者若认为下架有误，可提交反通知，说明权属或合理使用依据，站务复核后决定是否恢复。</p><h2 id="_5-重复侵权" tabindex="-1">5. 重复侵权 <a class="header-anchor" href="#_5-重复侵权" aria-label="Permalink to &quot;5. 重复侵权&quot;">​</a></h2><p>重复侵权或恶意投诉的账号将被限流或封禁，邀请链将作为溯源依据之一。</p><h2 id="_6-技术措施" tabindex="-1">6. 技术措施 <a class="header-anchor" href="#_6-技术措施" aria-label="Permalink to &quot;6. 技术措施&quot;">​</a></h2><ul><li>媒体 URL 需鉴权，<code>robots.txt</code> 禁止直链索引</li><li>速率限制与审计日志用于防止批量外泄</li></ul>',15)])])}const p=e(o,[["render",r]]);export{u as __pageData,p as default};
